INSERT INTO feature VALUES('effect-rows','effects','Effect rows','row-kind','implemented','uncommon','mainstream languages','A returner''s type carries the row of named interfaces it may perform, with typed payloads and replies, written `-F [I, …] A`: each interface named once whole, each instance of one by its label, `a : I`, and in no order of its own, so sequencing joins two rows, handling removes an interface, and a row is read where one holding more is asked. At a definition''s result the row is written before the value type, `-> [I, …] A`, the row of the returner the lowering inserts there; a row before a type anywhere else is refused. An entry names a host interface or a theory with its value sorts fixed, `-F [State.Eff with sort S = Integer] A`.','core-term core-checker core-incremental surface-grammar surface-lowering','corpus/model/control/handler-exits.gandr corpus/model/effects/hello.gandr corpus/pathological/effects/hello-unprovided.gandr corpus/model/control/effect-rows.gandr corpus/pathological/control/effect-rows.gandr corpus/ledger/syntax/f-type.result.gandr corpus/ledger/diagnostics/OutOfFragment.NotAtResult.gandr','corpus/model/control/handler-exits.gandr',NULL);
